"""Embedded base64 PNG icons ported from ``GMADieRoller/Image.py``."""

from __future__ import annotations

import base64

DICE_PNG = b''
DICE_LT_PNG = b''
DICE_LT_2_PNG = b''
# Corrupted Photoshop iTXt XMP metadata chunks stripped so libpng decodes LOCK_PNG and CHAT_PNG cleanly.
LOCK_PNG = b''
HIDDEN_PNG = b''
CHAT_PNG = b''
DICE_LARGE_PNG = b''

try:
    from PySide6.QtCore import Qt
    from PySide6.QtGui import QIcon, QPixmap

    QT_AVAILABLE = True
except ImportError:  # pragma: no cover
    QT_AVAILABLE = False


if QT_AVAILABLE:

    def load_qpixmap(b64_data: bytes, size: int = 16) -> QPixmap:
        """Decode base64 PNG bytes into a scaled ``QPixmap``."""
        raw = base64.b64decode(b64_data)
        pm = QPixmap()
        pm.loadFromData(raw, "PNG")
        if not pm.isNull() and size > 0 and (pm.width() != size or pm.height() != size):
            pm = pm.scaled(
                size,
                size,
                Qt.AspectRatioMode.KeepAspectRatio,
                Qt.TransformationMode.SmoothTransformation,
            )
        return pm

    def load_qicon(b64_data: bytes, size: int = 16) -> QIcon:
        """Decode base64 PNG bytes into a ``QIcon``."""
        return QIcon(load_qpixmap(b64_data, size=size))
